"""Seed data for the claims ledger (Plan 5.5): testable claims drawn from the Plan and the seven source papers P1-P7.

Rules of the ledger (Plan 5.5 and 1.4):

* every claim starts ``status="untested"`` - the papers are a map, not ground truth;
* ``prior="untrusted"`` for vendor material, author-reported / single-source results and anything about real hardware speed;
  ``prior="trusted"`` only for mathematics, closed-form derivations, byte arithmetic and findings that several independent
  studies agree on;
* ``expectation`` (optional) is the machine-checkable form used by :func:`forge.planner.claims.evaluate_claim`:
  ``{metric, expected, tolerance, direction}``; direction ``approx`` (|x-e| <= tol), ``at_least`` or ``at_most``;
* ``depends_rules`` is NOT stored here: it is derived from the rulebase (every rule lists the claims it relies on).

``location`` strings point at the paper's executive-summary finding / abstract item / equation / table, or at the Plan section
that cites the paper, so a reader can find the original statement.  Numbers are copied from those places, not recomputed.
"""
from __future__ import annotations

from typing import Any

T, U = "trusted", "untrusted"


def _c(id: str, paper: str, location: str, statement: str, prior: str, notes: str = "", expectation: dict[str, Any] | None = None) -> dict[str, Any]:
    return {"id": id, "source_paper": paper, "location": location, "statement": statement, "prior": prior, "notes": notes, "expectation": expectation}


